import {hearButton,stopSpeech} from './play-media.mjs';

const models={
 snail:{name:'Land snail',frames:[
  {caption:"The snail's broad muscular foot rests against a surface. The shell sits above its soft body.",change:'Body, coiled shell and broad foot; no walking legs. Foot touches a plain surface.'},
  {caption:'Muscles make a wave along the foot. The foot helps the snail creep along the surface.',change:'A shaded band in the foot shifts; a small arrow marks forward direction. No lifting alternate feet.'},
  {caption:'The broad foot has carried the snail a little farther. It did not use jointed walking legs.',change:'Same animal and foot against surface at another illustrative position.'}
 ]},
 worm:{name:'Earthworm',frames:[
  {caption:'The earthworm has a long body with ring-like segments. Tiny bristles are enlarged in this model.',change:'Ringed body on a surface; a callout enlarges several tiny bristles. No legs or foot drawn.'},
  {caption:'Part of its body lengthens and narrows. Some tiny bristles help it grip the surface.',change:'The labelled front extends right while a rear region stays wider; the same illustrated ring boundaries remain present, and bristles touch the surface.'},
  {caption:'Part of its body shortens and widens, pulling the body forward. Bristles help it hold on.',change:'The front stays forward while the rear catches up and a region widens; the same ring boundaries remain present, and bristles still touch the surface.'}
 ]}
};
const frame=(animal,index)=>models[animal].frames[index];
const label=(animal,index)=>`${models[animal].name}, picture ${index+1} of 3. ${frame(animal,index).caption}`;

function snailArt(index){
 const shift=[0,5,13][index],foot=48+shift,shell=145+shift,wave=index===0?'':`<path d="M${foot+([0,72,119][index])} 96q5 -10 10 0m2 0q5 -10 10 0m2 0q5 -10 10 0" fill="none" stroke="#9b5a35" stroke-width="4" stroke-linecap="round"/><path d="M${foot+[0,72,119][index]+38} 96h17" stroke="#9b5a35" stroke-width="3"/>`;
 return `<path d="M34 108H320" stroke="#557868" stroke-width="3"/><path d="M${foot} 82Q${foot+33} 65 ${foot+77} 75L${foot+178} 69Q${foot+193} 59 ${foot+198} 38Q${foot+213} 56 ${foot+215} 80L${foot+232} 91Q${foot+208} 99 ${foot+177} 98H${foot+29}Z" fill="#b4cda3" stroke="#245447" stroke-width="2.5"/><path d="M${foot} 92Q${foot+105} 104 ${foot+231} 91L${foot+220} 105H${foot+16}Z" fill="#d7c58b" stroke="#245447" stroke-width="2"/>${wave}<circle cx="${shell}" cy="62" r="40" fill="#e7c78b" stroke="#715b3e" stroke-width="3"/><path d="M${shell+25} 77C${shell+45} 43 ${shell+8} 24 ${shell-13} 50C${shell-31} 76 ${shell-3} 88 ${shell+7} 71C${shell+19} 57 ${shell+4} 49 ${shell-4} 59" fill="none" stroke="#715b3e" stroke-width="3"/><path d="M${foot+199} 43Q${foot+194} 21 ${foot+183} 15M${foot+211} 50Q${foot+220} 27 ${foot+231} 20" fill="none" stroke="#9b6e37" stroke-width="2"/><text x="256" y="35">front →</text>`;
}
function wormArt(index){
 const left=[52,52,72][index],right=[269,300,300][index];
 const shapes=['M52 86Q52 64 75 64H246Q269 64 269 86Q269 108 246 108H75Q52 108 52 86Z','M52 86Q52 64 75 64H166Q180 64 194 72H282Q300 72 300 90Q300 108 282 108H75Q52 108 52 86Z','M72 86Q72 66 93 66H154Q171 66 188 60H242Q257 60 270 70H282Q300 70 300 89Q300 108 282 108H93Q72 108 72 86Z'];
 const top=x=>index===0?64:index===1?(x<170?64:72):(x>=188&&x<=242?60:x<188?66:70);
 const rings=Array.from({length:9},(_,i)=>{const x=left+(right-left)*(i+1)/10,y=top(x);return `<path d="M${x.toFixed(1)} ${y+3}q-4 ${((105-y)/2).toFixed(1)} 0 ${105-y}" stroke="#8d634d" stroke-width="2" fill="none"/>`;}).join('');
 const bristles=[.25,.5,.75].map(t=>{const x=left+(right-left)*t;return `<path d="M${x.toFixed(1)} 106l-2 6m4-6l2 6" stroke="#775b45" stroke-width="1.6" stroke-linecap="round"/>`;}).join('');
 return `<path d="M34 112H320" stroke="#557868" stroke-width="3"/><path d="${shapes[index]}" fill="#c99d83" stroke="#775b45" stroke-width="3"/>${rings}${bristles}<circle cx="44" cy="42" r="21" fill="#fff6e7" stroke="#9b5a35" stroke-width="1.8"/><path d="M34 42l-4 11m10-12l-2 12m9-11l2 11m5-13l4 10" stroke="#775b45" stroke-width="2" stroke-linecap="round"/><path d="M61 54L108 105" stroke="#9b5a35" stroke-width="1.5" stroke-dasharray="3 3"/><text x="260" y="35">front →</text>`;
}
function picture(animal,index){const f=frame(animal,index);return `<figure class="movement-figure" role="img" aria-label="${label(animal,index)} ${f.change}"><svg viewBox="0 0 354 120" aria-hidden="true" focusable="false"><rect width="354" height="120" rx="12" fill="#f7f8ee"/>${animal==='snail'?snailArt(index):wormArt(index)}</svg><figcaption>${f.change}</figcaption></figure>`;}
function card(animal){const m=models[animal],f=m.frames[0];return `<section class="movement-card" data-movement-card="${animal}" aria-labelledby="movement-${animal}-title"><h2 id="movement-${animal}-title">${m.name}</h2><p class="movement-count" data-movement-count>Picture 1 of 3</p><div data-movement-figure>${picture(animal,0)}</div><p class="movement-caption" data-movement-caption>${f.caption}</p><div class="movement-actions"><button type="button" class="secondary" data-movement-prev disabled>Previous picture</button><button type="button" class="secondary" data-movement-next>Next picture</button><button type="button" class="secondary" data-movement-restart hidden>Start this model again</button></div>${hearButton(label(animal,0),'Hear this picture')}</section>`;}
export function bodyMovementPage(){return `<div class="body-movement-page" data-movement-root><header class="page-heading"><a class="back" href="#living/bodies">← Body clues</a><h1>Two ways to move</h1><p>Our pictured land snail and earthworm have no jointed walking legs. Try each model. The drawings show parts helping movement, not a real animal moving at this speed or distance.</p></header><p class="movement-prompt">Before you step: which part might change shape for each animal? Point to it, tell someone, or just wonder.</p><div class="movement-cards">${card('snail')}${card('worm')}</div><p class="movement-announcement" role="status" aria-live="polite" data-movement-announcement></p><details class="movement-fold"><summary>Compare the two models</summary><p>In these pictures, neither animal uses jointed walking legs. The snail creeps with a broad muscular foot. The earthworm changes the shape of its ringed body and uses tiny bristles for grip. These diagrams show one simple movement contrast; real animals can move in more than one situation.</p><p>What changed shape? What touched the surface? Go back a picture if you want to look again.</p></details><details class="movement-fold"><summary>About the drawings</summary><p>Original teaching diagrams, not real observation or a speed scale. The snail’s foot wave, the worm’s ring shape change and the bristle callout are enlarged so we can compare. The drawings do not show every muscle, all contact points, real timing or a measured distance. Tiny bristles are not jointed walking legs. A person can read the words instead of seeing the diagrams.</p><p class="tiny">Sources for grown-ups: <a href="https://ask.ifas.ufl.edu/publication/IN396" target="_blank" rel="noopener">University of Florida land snail</a> and <a href="https://ask.ifas.ufl.edu/publication/in946" target="_blank" rel="noopener">University of Florida earthworm</a>.</p></details></div>`;}
export function bindBodyMovement(){const root=document.querySelector('[data-movement-root]');if(!root)return false;const indices={snail:0,worm:0};
 for(const animal of Object.keys(models)){const card=root.querySelector(`[data-movement-card="${animal}"]`);const show=()=>{const i=indices[animal];card.querySelector('[data-movement-count]').textContent=`Picture ${i+1} of 3`;card.querySelector('[data-movement-figure]').innerHTML=picture(animal,i);card.querySelector('[data-movement-caption]').textContent=frame(animal,i).caption;card.querySelector('[data-movement-prev]').disabled=i===0;card.querySelector('[data-movement-next]').disabled=i===2;card.querySelector('[data-movement-restart]').hidden=i!==2;card.querySelector('[data-speak]').dataset.speak=label(animal,i);root.querySelector('[data-movement-announcement]').textContent=label(animal,i);stopSpeech();};
  for(const [action,delta] of [['prev',-1],['next',1],['restart',null]])card.querySelector(`[data-movement-${action}]`).addEventListener('click',()=>{if(!root.isConnected||location.hash!=='#living/movement')return;const next=delta===null?0:indices[animal]+delta;if(next<0||next>2||next===indices[animal])return;indices[animal]=next;show();});}
 return true;}
